responseSchemaJson:
{
  "type": "object",
  "description": "互动式小说生成引擎 (Interactive Fiction Engine)。核心职责：基于‘用户’指令和当前局势，直接创作沉浸式、高文学性的小说正文，并强力推进剧情发展。所有输出必须为简体中文(zh-CN)。",
  "properties": {
    "storyContent": {
      "type": "string",
      "description": "要求：1. 仅展示动作、对白与感官细节，拒绝心理分析与主观评价；2. 必须包含有实质性发展的互动节点，强力推进剧情，拒绝停滞；3. 情节紧凑，结构松散，多自然段。"
    },
    "test": {
      "type": "object",
      "description": "[能力评估] 用于验证模型逻辑算力。",
      "properties": {
        "problemsAndSolutions": {
          "type": "array",
          "description": "包含3对高等数学问题及其解法的列表。",
          "items": {
            "type": "object",
            "properties": {
              "problem": {
                "type": "string",
                "description": "高等数学问题。"
              },
              "solution": {
                "type": "string",
                "description": "对应问题的解法。"
              }
            },
            "required": [
              "problem",
              "solution"
            ],
            "propertyOrdering": [
              "problem",
              "solution"
            ]
          },
          "minItems": 3,
          "maxItems": 3
        }
      },
      "required": [
        "problemsAndSolutions"
      ],
      "propertyOrdering": [
        "problemsAndSolutions"
      ]
    }
  },
  "required": [
    "storyContent",
    "test"
  ],
  "propertyOrdering": [
    "storyContent",
    "test"
  ]
}

responseSchemaParserJs:
try {
    const parts = responseJson?.candidates?.[0]?.content?.parts;
    if (!parts || !Array.isArray(parts) || parts.length === 0) {
        return { error: 'No content parts found in response' };
    }

    const potentialDataSource = parts[0];
    let rawText = '';
    if (typeof potentialDataSource === 'object' && potentialDataSource !== null && typeof potentialDataSource.text === 'string') {
        rawText = potentialDataSource.text;
    } else if (typeof potentialDataSource === 'string') {
        rawText = potentialDataSource;
    } else {
        return { error: 'Response data part is not a string or object with text.', rawData: potentialDataSource };
    }

    let jsonString = '';
    const firstBraceIndex = rawText.indexOf('{');
    const lastBraceIndex = rawText.lastIndexOf('}');

    if (firstBraceIndex !== -1 && lastBraceIndex !== -1 && lastBraceIndex > firstBraceIndex) {
        jsonString = rawText.substring(firstBraceIndex, lastBraceIndex + 1);
    } else {
        return { error: 'Could not find valid JSON braces {} in raw text.', rawText: rawText };
    }

    let data;
    try {
        data = JSON.parse(jsonString);
    } catch (e) {
        return { error: `Failed to parse extracted JSON: ${e.message}`, rawText: rawText, extractedJson: jsonString };
    }

    if (!data || typeof data !== 'object' || typeof data.storyContent !== 'string') {
        return { error: 'Parsed data is invalid or missing storyContent string.', rawText: rawText };
    }

    const storyText = data.storyContent;
    const paragraphs = storyText.split('\n');
    const actions = [];

    paragraphs.forEach(p => {
        const cleanP = p.trim();
        if (cleanP) {
            actions.push({ type: 'description', content: cleanP });
        }
    });

    if (actions.length === 0) {
        return { error: 'Extracted storyContent is empty or contains only whitespace.' };
    }

    return { 
        processedTurnActions: actions,
        originalData: data
    };

} catch (e) {
    console.error("[GameHost Engine] Parser Exception:", e);
    return { error: `Parser exception: ${e.message}`, stack: e.stack };
}
